/* ---------- currency converter ---------- */
.cv{position:relative;max-width:400px;padding:16px;overflow:visible!important}
.cv-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.cv-head .t{font-size:15px;font-weight:600}
.cv-live{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}
.cv-live i{width:6px;height:6px;background:var(--success);animation:dot 1.6s ease-in-out infinite}
.cv-box{display:flex;flex-direction:column;gap:6px;padding:12px 14px;background:var(--panel);border:1px solid var(--icon-line);transition:border-color .2s}
.cv-box:focus-within{border-color:var(--accent)}
.cv-l{font-size:12px;color:var(--muted)}
.cv-r{display:flex;align-items:center;gap:10px}
.cv-r input,.cv-out{flex:1;min-width:0;background:transparent;border:0;outline:0;font:inherit;font-family:var(--mono);font-size:24px;font-weight:700;letter-spacing:-.5px;color:var(--text)}
.cv-cur{display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 8px 0 6px;border:1px solid var(--line);font-size:13.5px;font-weight:600;color:var(--text);transition:border-color .2s}
.cv-cur:hover{border-color:var(--icon-line)}
.cv-cur img,.cv-mi img{width:20px;height:20px;border-radius:50%}
.cv-cur .ms{font-size:13px;color:var(--muted)}
.cv-swap{position:relative;z-index:1;display:grid;place-items:center;width:34px;height:34px;margin:-10px auto;background:var(--panel);border:1px solid var(--icon-line);color:var(--text-dim);transition:transform .5s cubic-bezier(.34,1.56,.64,1),color .2s}
.cv-swap:hover{color:var(--text)}
.cv-swap.spin{transform:rotate(180deg)}
.cv-chips{display:flex;gap:6px;margin-top:12px}
.cv-chips button{padding:5px 10px;border:1px solid var(--line);font-size:12.5px;font-weight:500;color:var(--text-dim);transition:border-color .2s,color .2s}
.cv-chips button:hover{border-color:var(--icon-line);color:var(--text)}
.cv-rate{display:flex;align-items:center;justify-content:space-between;margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:13px;color:var(--text-dim)}
.cv-ch{font-family:var(--mono);font-size:12px;font-weight:700}
.cv-ch.up{color:var(--success)}.cv-ch.down{color:var(--danger)}
.cv-out.flash{animation:cv-flash .5s ease}
@keyframes cv-flash{from{opacity:.3;transform:translateY(3px)}to{opacity:1;transform:none}}
.cv-menu{position:absolute;z-index:6;width:220px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top right;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.cv-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.cv-mi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;font-size:13.5px;color:var(--text);transition:background-color .15s}
.cv-mi:hover{background:var(--chip)}
.cv-mi .n{color:var(--muted);font-size:12.5px}
.cv-mi .ms{margin-left:auto;color:var(--accent);opacity:0}
.cv-mi.sel .ms{opacity:1}
[data-style="soft"] .cv-box{border-radius:16px;border-width:1.5px}
[data-style="soft"] .cv-r input,[data-style="soft"] .cv-out{font-family:var(--sans);letter-spacing:-1px}
[data-style="soft"] .cv-cur,[data-style="soft"] .cv-chips button{border-radius:999px;border-width:1.5px}
[data-style="soft"] .cv-swap{border-radius:50%}
[data-style="soft"] .cv-live i{border-radius:50%}
[data-style="soft"] .cv-menu{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .cv-mi{border-radius:9px}
[data-style="soft"] .cv-ch{font-family:var(--sans)}
.cv-swap.cv-flip{transform:rotate(180deg)}

