{
  Object.assign(FLAGS, {"eu": "data:image/svg+xml;base64,", "ch": "data:image/svg+xml;base64,"});
  const cv = $('#cv'), amt = $('#cv-amt'), out = $('#cv-out'), menu = $('#cv-menu');
  // sample mid-market rates against the US dollar, for the demo only
  const CUR = [['USD','US dollar','us',1,0.1],['EUR','Euro','eu',0.92,-0.3],['GBP','British pound','gb',0.79,0.2],['PLN','Polish zloty','pl',3.98,-0.4],['CHF','Swiss franc','ch',0.88,0.1],['JPY','Japanese yen','jp',149.2,0.6]];
  let from = 'EUR', to = 'PLN', side = null;
  const get = c => CUR.find(x => x[0] === c);
  const num = () => +amt.value.replace(/[^\d.]/g, '') || 0;
  function curBtn(b, c){ const x = get(c); b.innerHTML = `<img src="${FLAGS[x[2]]}" alt="">${c}${ic('expand_more','sm')}`; }
  function calc(flash){
    const f = get(from), t = get(to), rate = t[3] / f[3], v = num() * rate;
    out.textContent = v.toLocaleString('en-US', { maximumFractionDigits: t[0] === 'JPY' ? 0 : 2, minimumFractionDigits: t[0] === 'JPY' ? 0 : 2 });
    if (flash){ out.classList.remove('flash'); void out.offsetWidth; out.classList.add('flash'); }
    $('#cv-rate').textContent = `1 ${from} = ${rate.toLocaleString('en-US', { maximumFractionDigits:4 })} ${to}`;
    const ch = +(t[4] - f[4]).toFixed(1), el = $('#cv-ch'); el.className = 'cv-ch ' + (ch >= 0 ? 'up' : 'down'); el.textContent = (ch >= 0 ? '+' : '') + ch + '% today';
    curBtn($('.cv-cur[data-side="from"]', cv), from); curBtn($('.cv-cur[data-side="to"]', cv), to);
  }
  $('#cv-chips').innerHTML = [100, 1000, 10000].map(v => `<button data-v="${v}">${v.toLocaleString('en-US')}</button>`).join('');
  $('#cv-chips').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; amt.value = (+b.dataset.v).toLocaleString('en-US'); calc(true); Sound.play('tick'); });
  amt.addEventListener('input', () => { const raw = amt.value.replace(/[^\d.]/g, ''); const [i, d] = raw.split('.'); amt.value = (i ? (+i).toLocaleString('en-US') : '') + (d !== undefined ? '.' + d.slice(0, 2) : ''); calc(false); });
  $('#cv-swap').addEventListener('click', e => { [from, to] = [to, from]; e.currentTarget.classList.toggle('cv-flip'); calc(true); Sound.play('tab'); });
  function openMenu(btn){
    side = btn.dataset.side; const cur = side === 'from' ? from : to, other = side === 'from' ? to : from;
    menu.innerHTML = CUR.filter(c => c[0] !== other).map(c => `<button class="cv-mi ${c[0] === cur ? 'sel' : ''}" data-c="${c[0]}"><img src="${FLAGS[c[2]]}" alt="">${c[0]}<span class="n">${c[1]}</span>${ic('check','sm')}</button>`).join('');
    const r = cv.getBoundingClientRect(), b = btn.getBoundingClientRect();
    menu.style.left = (b.right - r.left - 220) + 'px'; menu.style.top = (b.bottom - r.top + 6) + 'px';
    menu.classList.add('show'); Sound.play('open');
  }
  const closeMenu = () => { menu.classList.remove('show'); side = null; };
  cv.addEventListener('click', e => {
    const b = e.target.closest('.cv-cur'); if (b){ side === b.dataset.side ? closeMenu() : openMenu(b); return; }
    const mi = e.target.closest('.cv-mi'); if (mi){ if (side === 'from') from = mi.dataset.c; else to = mi.dataset.c; closeMenu(); calc(true); Sound.play('select'); }
  });
  document.addEventListener('pointerdown', e => { if (side && !menu.contains(e.target) && !e.target.closest('.cv-cur')) closeMenu(); });
  calc(false);
}
